const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    email: { type: 'string', description: 'the ad-contact email we started with' },
    emailVerdict: { type: 'string', enum: ['confirmed', 'corrected', 'unconfirmed'] },
    correctedEmail: { type: ['string', 'null'], description: 'the better ad email found on the publisher own site, or null' },
    emailSource: { type: ['string', 'null'], description: 'URL on the publisher own domain where the ad email was found' },
    publisherReachable: { type: 'boolean', description: 'did the publisher official website load' },
    titles: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          name: { type: 'string' },
          status: { type: 'string', enum: ['alive', 'dead', 'renamed', 'merged', 'uncertain'] },
          currentName: { type: ['string', 'null'], description: 'if renamed/merged, the title it became' },
          evidenceUrl: { type: ['string', 'null'] },
          note: { type: 'string', description: 'one line: what signal proved the status' },
        },
        required: ['name', 'status', 'note'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['email', 'emailVerdict', 'publisherReachable', 'titles', 'summary'],
};

function prompt(g) {
  const market = { NO:'Norway', SE:'Sweden', DK:'Denmark', FI:'Finland', DE:'Germany', AT:'Austria', CH:'Switzerland', UK:'United Kingdom', IE:'Ireland' }[g.market] || g.market;
  return [
    'You audit publishers for a native-advertising catalog. Be SKEPTICAL: assume nothing is still alive until you see a current signal. Many of these titles may have closed, merged, or been renamed. A wrong "alive" is worse than an honest "uncertain".',
    '',
    'Market: ' + market + ' (' + g.market + ')',
    'Ad-contact email on file: ' + g.email,
    'Titles to check (' + g.titles.length + '): ' + g.titles.map(t => '"' + t + '"').join(', '),
    '',
    'TASK 1 — AD EMAIL. Visit the PUBLISHER\'S OWN official website. Find its current ad-sales contact email (look on pages like annonse/annonser/annonsere/boka annons/anzeigen/werbung/advertising/mediakit/kontakt). Rules:',
    '- To read an email you MUST fetch RAW HTML with curl (WebFetch masks emails). Run: curl -sL --max-time 25 -A "Mozilla/5.0" <url> | grep -Eio "mailto:[^\"<> ]+|[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,}" | sort -u',
    '- If the on-file email appears on the site -> emailVerdict "confirmed".',
    '- If the site shows a DIFFERENT correct ad email -> "corrected" + correctedEmail + emailSource (the URL).',
    '- If you cannot find ANY ad email on the official site -> "unconfirmed". NEVER pattern-guess an address.',
    '',
    'TASK 2 — TITLES STILL PUBLISHING. For EACH title decide its status TODAY using web search + the publisher site:',
    '- "alive": clear current signal (recent dated articles, the title listed as active on the publisher\'s own brands page, a live working site).',
    '- "dead": evidence it ceased/closed.',
    '- "renamed" or "merged": folded into another title -> set currentName.',
    '- "uncertain": no clear live signal found. DEFAULT to this. Do NOT mark "alive" without a current signal; do NOT mark "dead"/"merged"/"renamed" without evidence.',
    'For multi-title portfolios, the publisher\'s own "our brands/titles" page is the best source — confirm each title appears there and is active. Always cite evidenceUrl.',
    '',
    'Prefer curl and WebSearch/WebFetch. Set publisherReachable=false only if the official site truly does not load. Return ONLY the structured output, echoing email=' + g.email + '.',
  ].join('\n');
}

phase('Verify');
log('Verifying ' + GROUPS.length + ' uncontacted publisher groups online (titles alive + ad email)');
const results = await parallel(GROUPS.map((g, i) => () =>
  agent(prompt(g), {
    label: g.market + ':' + g.email,
    phase: 'Verify',
    schema: SCHEMA,
    agentType: 'general-purpose',
  }).then(v => ({ input: g, verdict: v })).catch(() => ({ input: g, verdict: null }))
));
const ok = results.filter(r => r && r.verdict);
log('Done: ' + ok.length + '/' + GROUPS.length + ' groups returned verdicts');
return results;
